const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let s = '';
let n = 0;

rl.on('line', (line) => {
  if (s === '') {
    s = line.trim();
  } else {
    n = parseInt(line.trim(), 10);
    rl.close();
  }
});

