    min = Math.floor((len + n) / 2);
  } else {
    min = n;
  }
  max = Math.floor((len + n) / 2);

  let temp = 0;
  for (let i = 0; i < len; i++) {
    for (let j = 1; j * 2 + i <= len; j++) {
      let key = 1;
      for (let k = 1; k <= j; k++) {
        if (s[i + k - 1] !== s[i + k + j - 1]) {
          key = 0;
        }
      }
      if (key === 1) {
        if (j > temp) {
          temp = j;
        }
      }
    }
  }

  let ans = 0;
  for (let i = max; i >= min && ans === 0; i--) {
    let valid = true;
    for (let k = 1; k <= i - n; k++) {
      if (s[len - k] !== s[len - k - i]) {
        valid = false;
        break;
      }
    }
    if (valid) {
      ans = i;
    }
  }

  if (min > ans) {
    ans = min;
  }
  if (temp > ans) {
    ans = temp;
  }

  console.log(2 * ans);
